import { Readable } from "node:stream";
function main(): void {
  const chunks: Buffer[] = [];
  const hex = "68656c6c6f";
  const nums = [104, 105];
  const r = Readable.from([Buffer.from("ab"), Buffer.from("cd")]);
  r.on("data", (c: Buffer) => { chunks.push(c); });
  r.on("end", () => {
    const all = Buffer.concat(chunks);
    console.log(all.length, all.toString());
    const h = Buffer.from(hex, "hex");
    console.log(h.length, h.toString());
    const n = Buffer.from(nums);
    console.log(n.length, n);
    console.log(Buffer.from(hex).length);
  });
}
